void Solver::rephase() {
    int phase_choice = rand() % 100;

    if (phase_choice < 70) {
        // 70% chance: Use current variable assignments
        for (int i = 1; i <= vars; i++) {
            saved[i] = value[i] == 0 ? saved[i] : value[i];
        }
    }
    else if (phase_choice < 85) {
        // 15% chance: Use local best phases
        for (int i = 1; i <= vars; i++) {
            saved[i] = local_best[i];
        }
    }
    else if (phase_choice < 90) {
        // 5% chance: Invert local best phases
        for (int i = 1; i <= vars; i++) {
            saved[i] = -local_best[i];
        }
    }
    else {
        // 10% chance: Random phases
        for (int i = 1; i <= vars; i++) {
            saved[i] = rand() % 2 ? 1 : -1;
        }
    }

    // Original rephase parameters
    rephases = 0;
    threshold *= 0.85;  // Slightly more aggressive threshold reduction
    rephase_limit += 12288;  // Increase rephase limit more
}
